<script setup lang="ts">
// AI 教练：会话详情（只读回溯，设计文档 §8）
//
// 数据：GET /ai/conversation?id= → AiConversationDetailView{ conversation, messages }。
// 消息渲染直接复用浮窗的 AiMessageList / AiMessageItem：
// thinking 折叠、工具调用过程、动作卡片历史状态都由那两个组件负责，这里不重复实现。
//
// 只读语义：本页不渲染浮窗、也不注入 saveHandler（judge_parse_save 卡片按「未接入」展示）；
// 「继续对话」把会话载入全局浮窗（浮窗由 App.vue 全局挂载）后由用户继续追问。

import { computed, onMounted, ref, watch } from "vue";
import { useRoute, useRouter } from "vue-router";
import { useCurrentInstance } from "@/util";
import { ShowErrorTips, ShowTextTipsSuccess, ShowTextTipsWarn } from "@/util/tips";
import { useBreakpoint } from "@/composables/useBreakpoint";
import { MapHistoryMessages, ResolveAiErrorText, useAiCoachStore } from "@/stores/aiCoach.ts";
import { GetAiConversation, PostAiConversationDelete } from "@/apis/ai-conversation.ts";
import AiMessageList from "@/components/ai/AiMessageList.vue";
import {
  CanOpenConversationRef,
  GetConversationFullTimeText,
  GetConversationRefLabel,
  GetConversationSceneTitle,
  GetConversationTitle,
  OpenConversationRef,
} from "@/views/ai/ai-conversation-display.ts";
import type { AiConversationDetail, AiConversationItem } from "@/apis/ai-conversation.ts";
import type { AiCoachMessage } from "@/stores/aiCoach.ts";

const route = useRoute();
const router = useRouter();
const { globalProperties } = useCurrentInstance();
const { isMobile } = useBreakpoint();
// 复用浮窗的 store：继续对话、场景名缓存都与浮窗保持一致
const store = useAiCoachStore();

const conversation = ref<AiConversationItem | null>(null);
const messages = ref<AiCoachMessage[]>([]);
const loading = ref(false);
const errorCode = ref(0);
const errorMessage = ref("");

/**
 * 路由参数 → 会话 id。
 * 路由写成 `:id+`（与 judge-detail 等既有详情页一致），重复参数拿到的是数组，这里统一取第一段。
 */
const conversationId = computed(() => {
  const raw = route.params.id;
  const text = Array.isArray(raw) ? raw[0] : raw;
  const id = Number(text);
  return Number.isInteger(id) && id > 0 ? id : 0;
});

const title = computed(() => (conversation.value ? GetConversationTitle(conversation.value) : "会话详情"));

const refLabel = computed(() => (conversation.value ? GetConversationRefLabel(conversation.value) : ""));

const canOpenRef = computed(() => (conversation.value ? CanOpenConversationRef(conversation.value) : false));

async function loadConversation() {
  loading.value = true;
  errorCode.value = 0;
  errorMessage.value = "";
  try {
    if (conversationId.value <= 0) {
      // id 非法时不必打接口：直接按「会话不存在」的文案提示，并给出返回列表的出口
      errorMessage.value = "会话地址不正确，请从会话列表进入";
      messages.value = [];
      return;
    }
    const res = await GetAiConversation(conversationId.value);
    if (res.code !== 0) {
      conversation.value = null;
      messages.value = [];
      errorCode.value = res.code;
      // 非本人或不存在统一返回 100096，文案由 GetText 给出
      errorMessage.value = ResolveAiErrorText("载入会话失败，请稍后重试", res.code);
      return;
    }
    const detail = res.data as AiConversationDetail;
    conversation.value = detail.conversation;
    // 历史消息 → 浮窗同款渲染结构（工具结果并回所在 assistant 气泡）
    messages.value = MapHistoryMessages(detail.messages ?? []);
  } catch (e) {
    console.error("load ai conversation detail failed:", e);
    errorMessage.value = "载入会话失败，请稍后重试";
  } finally {
    loading.value = false;
  }
}

/** 底部「继续对话」：打开全局浮窗并载入本会话 */
async function handleContinue() {
  if (store.generating) {
    ShowTextTipsWarn(globalProperties, "AI 正在生成中，请先停止或等本轮结束后再切换会话");
    return;
  }
  await store.open();
  await store.loadConversation(conversationId.value);
}

function handleBack() {
  void router.push({ name: "ai-conversation" });
}

async function handleOpenRef() {
  if (conversation.value && canOpenRef.value) {
    await OpenConversationRef(conversation.value);
  }
}

// ── 删除（二次确认）──

const deleteVisible = ref(false);
const deleting = ref(false);

function handleOpenDelete() {
  deleteVisible.value = true;
}

async function handleSubmitDelete() {
  if (!conversation.value) {
    return;
  }
  const id = conversation.value.id;
  deleting.value = true;
  try {
    const res = await PostAiConversationDelete(id);
    if (res.code !== 0) {
      ShowErrorTips(globalProperties, res.code);
      return;
    }
    store.conversations = store.conversations.filter((item) => item.id !== id);
    // 删掉的正是浮窗里载入的会话：重置浮窗，避免继续追问一个已不存在的会话
    if (store.conversationId === id) {
      store.reset();
      store.close();
    }
    deleteVisible.value = false;
    ShowTextTipsSuccess(globalProperties, "已删除会话");
    handleBack();
  } catch (e) {
    console.error("delete ai conversation failed:", e);
    ShowTextTipsWarn(globalProperties, "删除失败，请稍后重试");
  } finally {
    deleting.value = false;
  }
}

onMounted(() => {
  // 场景元信息与会话详情并行加载：场景名由 /ai/scene 提供（与浮窗、列表页共用缓存），
  // 晚到时模板里的场景标签会自动重渲染
  void store.refreshSceneMeta();
  void loadConversation();
});

// 组件被复用时（例如在详情页之间直接跳转）按新 id 重新加载，避免残留上一条会话的消息
watch(conversationId, () => {
  void loadConversation();
});
</script>

<template>
  <t-card class="ai-detail-card" :title="title">
    <template #actions>
      <t-space size="small">
        <t-button variant="text" @click="handleBack">
          <template #icon><t-icon name="rollback" /></template>
          返回列表
        </t-button>
        <t-button v-if="conversation" theme="danger" variant="text" @click="handleOpenDelete">
          <template #icon><t-icon name="delete" /></template>
          删除
        </t-button>
      </t-space>
    </template>

    <t-loading :loading="loading" size="small" show-overlay text="加载中...">
      <!-- 错误态：错误码经 GetText 出中文 -->
      <div v-if="errorMessage" class="ai-detail-error">
        <t-alert theme="error" :message="errorMessage" />
        <div class="ai-detail-error-footer">
          <span v-if="errorCode > 0" class="ai-detail-muted">错误码 {{ errorCode }}</span>
          <t-button theme="primary" variant="outline" @click="handleBack">返回列表</t-button>
        </div>
      </div>

      <template v-else-if="conversation">
        <!-- 会话元信息：场景、关联对象、消息数、累计 token、创建/更新时间 -->
        <div class="ai-detail-meta">
          <div class="ai-detail-meta-row">
            <t-tag size="small" variant="light">{{ GetConversationSceneTitle(store.sceneList, conversation.scene) }}</t-tag>
            <span v-if="refLabel" class="ai-detail-ref" :class="{ 'is-link': canOpenRef }" @click="handleOpenRef">
              <t-icon v-if="canOpenRef" name="link" />
              {{ refLabel }}
            </span>
          </div>
          <div class="ai-detail-meta-row ai-detail-muted">
            <span>{{ conversation.message_count }} 条消息</span>
            <span>累计 {{ conversation.total_tokens }} tokens</span>
            <span>创建于 {{ GetConversationFullTimeText(conversation, "insert_time") }}</span>
            <span>更新于 {{ GetConversationFullTimeText(conversation, "modify_time") }}</span>
          </div>
        </div>

        <!-- 只读消息流：复用浮窗组件（thinking 折叠、工具调用过程、动作卡片历史状态） -->
        <div class="ai-detail-messages">
          <AiMessageList :messages="messages" :generating="false" />
        </div>

        <!-- 底部继续对话：载入全局浮窗 -->
        <div class="ai-detail-footer">
          <span class="ai-detail-muted">继续对话会在右下角打开 AI 教练浮窗，并接着这条会话往下聊。</span>
          <t-button theme="primary" @click="handleContinue">
            <template #icon><t-icon name="chat" /></template>
            继续对话
          </t-button>
        </div>
      </template>
    </t-loading>

    <!-- 删除二次确认 -->
    <t-dialog
      v-model:visible="deleteVisible"
      header="删除会话"
      :width="isMobile ? '90%' : '420px'"
      :confirm-btn="{ content: '删除', theme: 'danger', loading: deleting }"
      @confirm="handleSubmitDelete"
    >
      <p>确定要删除会话「{{ title }}」吗？</p>
      <p class="ai-detail-muted">删除后该会话的全部消息都会一并移除，且无法恢复。</p>
    </t-dialog>
  </t-card>
</template>

